"""Offline tests for the commit-msg hook installer."""

import importlib.util
import os
import subprocess
import tempfile
import unittest
from pathlib import Path
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[1]
HELPER = ROOT / "files/scripts/install_commit_hooks.py"
SPEC = importlib.util.spec_from_file_location("install_commit_hooks", HELPER)
installer = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(installer)

HOOK = """#!/bin/sh
# Managed by ansible-role-git. Do not edit this file directly.
exit 0
"""


class InstallCommitHooksTests(unittest.TestCase):
    def setUp(self) -> None:
        self.temporary = tempfile.TemporaryDirectory()
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name)
        self.template = self.root / "commit-msg"
        self.template.write_text(HOOK, encoding="utf-8")
        environment = patch.dict(
            os.environ,
            {
                "HOME": str(self.root),
                "GIT_CONFIG_GLOBAL": str(self.root / "gitconfig"),
                "GIT_CONFIG_NOSYSTEM": "1",
            },
        )
        environment.start()
        self.addCleanup(environment.stop)
        self.repo = self.root / "repo"
        self.repo.mkdir()
        subprocess.run(
            ["git", "init", "--quiet", str(self.repo)],
            check=True,
            capture_output=True,
        )

    def install(self, on_conflict: str = "skip") -> dict:
        return installer.install(self.repo, self.template, on_conflict)

    def hook(self) -> Path:
        return self.repo / ".git" / "hooks" / "commit-msg"

    def test_installs_and_is_idempotent(self) -> None:
        self.assertEqual(self.install()["status"], "installed")
        self.assertEqual(self.hook().read_text(encoding="utf-8"), HOOK)
        self.assertEqual(self.hook().stat().st_mode & 0o777, 0o755)
        self.assertEqual(self.install()["status"], "unchanged")

    def test_skips_unmanaged_hook(self) -> None:
        self.hook().write_text("#!/bin/sh\n# custom\nexit 0\n", encoding="utf-8")
        result = self.install()
        self.assertEqual(result["status"], "skipped")
        self.assertIn("unmanaged", result["reason"])

    def test_fails_on_unmanaged_hook(self) -> None:
        self.hook().write_text("#!/bin/sh\n# custom\nexit 0\n", encoding="utf-8")
        with self.assertRaisesRegex(ValueError, "unmanaged"):
            self.install("fail")

    def test_updates_managed_hook(self) -> None:
        self.hook().write_text(
            "#!/bin/sh\n# Managed by ansible-role-git\nold\n", encoding="utf-8"
        )
        self.assertEqual(self.install()["status"], "updated")

    def test_skips_core_hooks_path(self) -> None:
        subprocess.run(
            [
                "git",
                "-C",
                str(self.repo),
                "config",
                "core.hooksPath",
                str(self.root / "hooks"),
            ],
            check=True,
            capture_output=True,
        )
        result = self.install()
        self.assertEqual(result["status"], "skipped")
        self.assertIn("core.hooksPath", result["reason"])

    def test_skips_non_repository(self) -> None:
        missing = self.root / "missing"
        result = installer.install(missing, self.template, "skip")
        self.assertEqual(result["status"], "skipped")
        self.assertIn("not a cloned repository", result["reason"])

    def test_cli_accepts_repos_json(self) -> None:
        result = subprocess.run(
            [
                "python3",
                str(HELPER),
                "--template",
                str(self.template),
                "--repos-json",
                f'["{self.repo}"]',
            ],
            capture_output=True,
            text=True,
            check=False,
        )
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn('"status": "installed"', result.stdout)


if __name__ == "__main__":
    unittest.main()
